describe("abort signal already aborted", () => {
  it("does not spawn a subprocess for an already aborted request", async () => {
    const model = mockModels[0] as any;
    const context = { messages: [{ role: "user", content: "Hello" }] };
    const controller = new AbortController(); controller.abort();
    const stream = streamViaCli(model, context, { signal: controller.signal });
    await vi.advanceTimersByTimeAsync(0);
    expect(spawn).not.toHaveBeenCalled();
    expect(stream.push).toHaveBeenCalledWith(expect.objectContaining({ type: "error", reason: "aborted" }));
    expect(stream.end).toHaveBeenCalledOnce();
  });
});

